  function renderTeachers() {
    const track = document.getElementById('teachersTrack');
    track.innerHTML = TEACHERS.map(t => `
      <div class="teacher-card" role="listitem">
        <div class="teacher-photo-placeholder" style="background: linear-gradient(160deg, ${t.color}, white);" aria-hidden="true">
