          <div class="teacher-specialty">${t.specialty}</div>
        </div>
      </div>
    `).join('');
  }

  let carouselOffset = 0;
  const CARD_WIDTH = 235; // card width + gap

  function scrollCarousel(dir) {
    const track = document.getElementById('teachersTrack');
    const maxOffset = (TEACHERS.length - 4) * CARD_WIDTH;
    carouselOffset = Math.max(0, Math.min(maxOffset, carouselOffset + dir * CARD_WIDTH * 2));
    track.style.transform = `translateX(-${carouselOffset}px)`;
  }

  /* ─── Course tab switching ─── */
  function renderCourses(category) {
    const grid = document.getElementById('course-grid');
    const filtered = COURSES.filter(c => c.category.includes(category));
    const display = filtered.length ? filtered : COURSES.slice(0, 8);

    grid.style.opacity = '0';
    grid.style.transform = 'translateY(8px)';

    setTimeout(() => {
      grid.innerHTML = display.map(c => `
        <article class="course-card" tabindex="0" role="button" aria-label="View course: ${c.title}">
          <div class="course-thumb-placeholder" style="background: linear-gradient(135deg, ${c.color}, #fff);" aria-hidden="true">
