            <div class="course-meta">
              <span class="course-meta-item"><span class="course-meta-icon">👤</span> ${c.students} students</span>
              <span class="course-meta-item"><span class="course-meta-icon">⏱</span> ${c.duration}</span>
            </div>
          </div>
        </article>
      `).join('');
      grid.style.transition = 'opacity 250ms ease, transform 250ms ease';
      grid.style.opacity = '1';
      grid.style.transform = 'translateY(0)';
    }, 120);
  }

  function switchTab(el, category) {
    document.querySelectorAll('.course-tab').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-selected', 'false');
    });
    el.classList.add('active');
    el.setAttribute('aria-selected', 'true');
    renderCourses(category);
  }

  /* ─── FAQ accordion ─── */
  function toggleFaq(btn) {
    const item = btn.closest('.faq-item');
    const isOpen = item.classList.contains('open');

    // Close all
    document.querySelectorAll('.faq-item.open').forEach(el => {
      el.classList.remove('open');
      el.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
    });

    // Open clicked (if it was closed)
    if (!isOpen) {
      item.classList.add('open');
      btn.setAttribute('aria-expanded', 'true');
    }
  }

  /* ─── Modals ─── */
  function openEmailModal(e) {
    e && e.preventDefault();
    document.getElementById('emailModal').classList.add('open');
    document.body.style.overflow = 'hidden';
    setTimeout(() => document.getElementById('modal-email').focus(), 100);
  }

  function closeEmailModal() {
    document.getElementById('emailModal').classList.remove('open');
    document.body.style.overflow = '';
  }

  function closeModalOnOverlay(e) {
    if (e.target === e.currentTarget) closeEmailModal();
  }

  function openGoogleAuth(e) {
    e.preventDefault();
    // In production this would initiate OAuth — show placeholder confirmation
    alert('Google OAuth flow would initiate here.');
