  }

  // Keyboard: Escape closes modal
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeEmailModal();
  });

  // Mobile nav toggle placeholder
  function toggleMobileMenu() {
    const links = document.querySelector('.nav-links');
    if (links) {
      if (links.style.display === 'flex') {
        links.style.display = 'none';
      } else {
        links.style.cssText = 'display:flex;flex-direction:column;position:absolute;top:4rem;left:0;right:0;background:rgba(0,0,0,0.97);padding:1rem 1.5rem;gap:0.25rem;backdrop-filter:blur(12px);z-index:99;';
